  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  setting_key                  varchar(128) NOT NULL,
  value                        jsonb NOT NULL,
  value_type                   varchar(40) NOT NULL CHECK (value_type IN ('STRING', 'NUMBER', 'BOOLEAN', 'JSON', 'DURATION', 'AMOUNT')),
  category                     varchar(64),
  description                  varchar(500),
  is_sensitive                 boolean NOT NULL DEFAULT false,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_tenant_setting_setting_key UNIQUE (tenant_id, setting_key)
);
COMMENT ON TABLE tenant_setting IS 'Typed tenant-level setting (key/value) used by all services';
COMMENT ON COLUMN tenant_setting.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN tenant_setting.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN tenant_setting.created_at IS 'Creation time';
COMMENT ON COLUMN tenant_setting.created_by IS 'Principal that created the row';
COMMENT ON COLUMN tenant_setting.updated_at IS 'Last update time';
COMMENT ON COLUMN tenant_setting.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN tenant_setting.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN tenant_setting.setting_key IS 'Setting key, e.g. payments.default_rail';
COMMENT ON COLUMN tenant_setting.value IS 'Setting value';
COMMENT ON COLUMN tenant_setting.value_type IS 'Value type';
COMMENT ON COLUMN tenant_setting.category IS 'Grouping for the console';
COMMENT ON COLUMN tenant_setting.description IS 'What the setting controls';
COMMENT ON COLUMN tenant_setting.is_sensitive IS 'Masked in the console and audit log';
COMMENT ON COLUMN tenant_setting.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_setting.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_setting.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_setting.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_setting.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_tenant_setting_tenant ON tenant_setting (tenant_id, created_at);
ALTER TABLE tenant_setting ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenant_setting USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_tenant_setting_touch BEFORE UPDATE ON tenant_setting FOR EACH ROW EXECUTE FUNCTION touch_row();

