-- tenant_branding: White-label branding per channel (logo, colours, fonts, copy, domains, senders)
CREATE TABLE tenant_branding (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  legal_entity_id              uuid REFERENCES legal_entity(id),
  channel                      varchar(40) NOT NULL DEFAULT 'ALL' CHECK (channel IN ('ALL', 'MOBILE', 'WEB', 'CONSOLE', 'EMAIL', 'SMS', 'USSD')),
  app_name                     varchar(80) NOT NULL,
  logo_document_id             uuid,
  icon_document_id             uuid,
  primary_color                varchar(9) NOT NULL,
  secondary_color              varchar(9),
  accent_color                 varchar(9),
  font_family                  varchar(80),
  theme_tokens                 jsonb,
  default_locale               varchar(10) NOT NULL DEFAULT 'en',
  supported_locales            jsonb,
  custom_domain                varchar(255),
  support_email                varchar(320),
  support_phone                varchar(20),
  terms_url                    varchar(500),
  privacy_url                  varchar(500),
  email_sender_name            varchar(120),
  email_sender_address         varchar(320),
  sms_sender_id                varchar(11),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_tenant_branding_1 UNIQUE (tenant_id, legal_entity_id, channel)
);
COMMENT ON TABLE tenant_branding IS 'White-label branding per channel (logo, colours, fonts, copy, domains, senders)';
COMMENT ON COLUMN tenant_branding.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN tenant_branding.tenant_id IS 'Owning tenant; enforced by row-level security';
