COMMENT ON COLUMN tenant_branding.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN tenant_branding.legal_entity_id IS 'Brand per legal entity (empty = tenant-wide)';
COMMENT ON COLUMN tenant_branding.channel IS 'Channel the branding applies to';
COMMENT ON COLUMN tenant_branding.app_name IS 'Product / app name shown to customers';
COMMENT ON COLUMN tenant_branding.logo_document_id IS 'Logo';
COMMENT ON COLUMN tenant_branding.icon_document_id IS 'App icon / favicon';
COMMENT ON COLUMN tenant_branding.primary_color IS 'Hex colour, e.g. #1F3864';
COMMENT ON COLUMN tenant_branding.secondary_color IS 'Hex colour';
COMMENT ON COLUMN tenant_branding.accent_color IS 'Hex colour';
COMMENT ON COLUMN tenant_branding.font_family IS 'Font family';
COMMENT ON COLUMN tenant_branding.theme_tokens IS 'Full design-token overrides (light and dark)';
COMMENT ON COLUMN tenant_branding.default_locale IS 'Default locale';
COMMENT ON COLUMN tenant_branding.supported_locales IS 'Enabled locales (BCP 47 tags)';
COMMENT ON COLUMN tenant_branding.custom_domain IS 'Custom domain for web apps';
COMMENT ON COLUMN tenant_branding.support_email IS 'Support email';
COMMENT ON COLUMN tenant_branding.support_phone IS 'Support phone';
COMMENT ON COLUMN tenant_branding.terms_url IS 'Terms and conditions URL';
COMMENT ON COLUMN tenant_branding.privacy_url IS 'Privacy policy URL';
COMMENT ON COLUMN tenant_branding.email_sender_name IS 'Email sender name';
COMMENT ON COLUMN tenant_branding.email_sender_address IS 'Email sender address';
COMMENT ON COLUMN tenant_branding.sms_sender_id IS 'Alphanumeric SMS sender id';
COMMENT ON COLUMN tenant_branding.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_branding.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_branding.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_branding.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN tenant_branding.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_tenant_branding_tenant ON tenant_branding (tenant_id, created_at);
CREATE INDEX ix_tenant_branding_legal_entity_id ON tenant_branding (legal_entity_id);
CREATE INDEX ix_tenant_branding_logo_document_id ON tenant_branding (logo_document_id);
CREATE INDEX ix_tenant_branding_icon_document_id ON tenant_branding (icon_document_id);
ALTER TABLE tenant_branding ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenant_branding USING (tenant_id = current_setting('app.tenant_id')::uuid);
